    #[test]
    fn example_e1_1970_01_01() {
        let value = Time(2208988800);
        assert_eq!(value.unix_seconds(), 0);
        assert_eq!(parse(&print(value)), Ok(value));
    }

    #[test]
    fn example_e2_1976_01_01() {
        let value = Time(2398291200);
        assert_eq!(value.unix_seconds(), 189302400);
        assert_eq!(parse(&print(value)), Ok(value));
    }

